'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { CheckCircle2, XCircle, Workflow } from 'lucide-react';

export default function ODApprovalPage() {
    const [requests, setRequests] = useState<any[]>([]);

    const load = async () => {
        try {
            const res = await api.get<any[]>('/api/hod/od/pending');
            if (res.success) setRequests(res.data);
        } catch (e) { }
    };

    useEffect(() => { load(); }, []);

    const handleAction = async (odId: string, action: string) => {
        try {
            await api.patch(`/api/hod/od/${odId}/action`, { action });
            load();
        } catch (e) { }
    };

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                OD Approval (HOD)
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Final approval for student OD requests</p>

            {requests.length === 0 ? (
                <div className="card" style={{ textAlign: 'center', padding: 48, color: '#8a9aa2' }}>
                    <Workflow size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p>No pending OD requests for HOD approval</p>
                </div>
            ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                    {requests.map((r) => (
                        <div key={r.id} className="card" style={{ padding: 20 }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                <div>
                                    <div style={{ fontSize: 15, fontWeight: 600, color: '#142B34', marginBottom: 4 }}>
                                        Student: {r.student_id}
                                    </div>
                                    <div style={{ fontSize: 13, color: '#5a6a72', marginBottom: 4 }}>
                                        Date: {r.date} • Subject: {r.subject_id}
                                    </div>
                                    <div style={{ fontSize: 13, color: '#059669', marginBottom: 8 }}>
                                        ✓ Faculty approved by: {r.faculty_action_by}
                                    </div>
                                    <div style={{ fontSize: 14, color: '#142B34' }}>{r.reason}</div>
                                </div>
                                <div style={{ display: 'flex', gap: 8 }}>
                                    <button className="btn-primary btn-sm" onClick={() => handleAction(r.id, 'approve')}>
                                        <CheckCircle2 size={14} /> Approve
                                    </button>
                                    <button className="btn-danger" onClick={() => handleAction(r.id, 'reject')}>
                                        <XCircle size={14} /> Reject
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}
